package com.demo.invoicedesk;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class GdtCaptchaLearningService {
 private final JdbcTemplate db;
 @Value("${invoice-desk.captcha-learning-enabled:false}") private boolean enabled;
 public GdtCaptchaLearningService(JdbcTemplate db){this.db=db;}
 public record Glyph(UUID id,int order,int x,int y,int width,int height,String imageBase64,String predicted,double confidence){}
 public record Reading(UUID sampleId,String text,String googleText,String localText,String reviewImageBase64,String sourceImageBase64,String cleanedImageBase64,List<Glyph> glyphs){}
 public record Feedback(String correctedText,boolean correct,List<UUID> glyphOrder,List<String> glyphImagesBase64){}
 public record CharacterSummary(String character,long variants,String firstLearnedAt,String lastLearnedAt){}
 public record CharacterVariant(UUID id,UUID sampleId,String imageBase64,double confidence,String learnedAt){}
 private record Match(String value,double confidence){}
 private record Pending(UUID id,int order,GdtCaptchaImage.Glyph glyph,Match match){}
 private record Candidate(GdtCaptchaImage.Analysis analysis,List<Pending> pending,List<Glyph> glyphs,String text){}
 public boolean enabled(){return enabled;}

 public Map<String,Object> preview(InvoiceDeskService.Scope scope,byte[] source)throws Exception{if(!enabled)return Map.of("text","","confident",false,"glyphs",List.of());Candidate candidate=candidate(scope.tenantId(),source,6);return Map.of("text",candidate.text(),"confident",strong(candidate),"glyphs",candidate.glyphs());}

 /** Returns a persisted local result only when every split glyph is already known confidently. */
 @Transactional public Reading recognize(InvoiceDeskService.Scope scope,byte[] source)throws Exception{
  if(!enabled)throw new IllegalStateException("CAPTCHA learning is disabled.");
  Candidate candidate=candidate(scope.tenantId(),source,6);if(!strong(candidate))return null;UUID sample=UUID.randomUUID();Instant now=Instant.now();
  db.update("INSERT INTO invoice_desk_gdt_captcha_sample(id,tenant_id,company_id,source_png,cleaned_png,review_png,google_text,local_text,selected_text,corrected_text,review_state,reviewed_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",sample,scope.tenantId(),scope.companyId(),source,GdtCaptchaImage.png(candidate.analysis().cleaned()),GdtCaptchaImage.png(candidate.analysis().review()),"",candidate.text(),candidate.text(),candidate.text(),"CORRECT",Timestamp.from(now));
  for(Pending value:candidate.pending()){var box=value.glyph().box();boolean novel=value.match().confidence()<.985;db.update("INSERT INTO invoice_desk_gdt_captcha_glyph(id,sample_id,tenant_id,glyph_order,x,y,width,height,glyph_png,fingerprint,predicted_char,confidence,confirmed_char,accepted) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",value.id(),sample,scope.tenantId(),value.order(),box.x(),box.y(),box.width(),box.height(),GdtCaptchaImage.png(value.glyph().image()),value.glyph().fingerprint(),value.match().value(),value.match().confidence(),novel?value.match().value():"",novel);}
  return new Reading(sample,candidate.text(),"",candidate.text(),Base64.getEncoder().encodeToString(GdtCaptchaImage.png(candidate.analysis().review())),Base64.getEncoder().encodeToString(source),Base64.getEncoder().encodeToString(GdtCaptchaImage.png(candidate.analysis().cleaned())),candidate.glyphs());
 }

 @Transactional public Reading remember(InvoiceDeskService.Scope scope,byte[] source,String googleText)throws Exception{
  if(!enabled)throw new IllegalStateException("CAPTCHA learning is disabled.");
  String google=clean(googleText);Candidate candidate=candidate(scope.tenantId(),source,6);UUID sample=UUID.randomUUID();String selected=choose(google,candidate.text(),candidate.glyphs());db.update("INSERT INTO invoice_desk_gdt_captcha_sample(id,tenant_id,company_id,source_png,cleaned_png,review_png,google_text,local_text,selected_text) VALUES (?,?,?,?,?,?,?,?,?)",sample,scope.tenantId(),scope.companyId(),source,GdtCaptchaImage.png(candidate.analysis().cleaned()),GdtCaptchaImage.png(candidate.analysis().review()),google,candidate.text(),selected);
  for(Pending value:candidate.pending()){var box=value.glyph().box();db.update("INSERT INTO invoice_desk_gdt_captcha_glyph(id,sample_id,tenant_id,glyph_order,x,y,width,height,glyph_png,fingerprint,predicted_char,confidence) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",value.id(),sample,scope.tenantId(),value.order(),box.x(),box.y(),box.width(),box.height(),GdtCaptchaImage.png(value.glyph().image()),value.glyph().fingerprint(),value.match().value(),value.match().confidence());}
  return new Reading(sample,selected,google,candidate.text(),Base64.getEncoder().encodeToString(GdtCaptchaImage.png(candidate.analysis().review())),Base64.getEncoder().encodeToString(source),Base64.getEncoder().encodeToString(GdtCaptchaImage.png(candidate.analysis().cleaned())),candidate.glyphs());
 }
 @Transactional public void feedback(InvoiceDeskService.Scope scope,UUID sampleId,Feedback feedback)throws Exception{
  if(!enabled)throw new IllegalStateException("CAPTCHA learning is disabled.");
  String corrected=clean(feedback==null?null:feedback.correctedText());if(corrected.length()!=6)throw new IllegalArgumentException("Corrected CAPTCHA must contain exactly 6 letters or numbers.");
  Integer owned=db.queryForObject("SELECT COUNT(*) FROM invoice_desk_gdt_captcha_sample WHERE id=? AND tenant_id=? AND company_id=?",Integer.class,sampleId,scope.tenantId(),scope.companyId());if(owned==null||owned!=1)throw new IllegalArgumentException("CAPTCHA learning sample was not found.");
  List<UUID> stored=db.query("SELECT id FROM invoice_desk_gdt_captcha_glyph WHERE sample_id=? ORDER BY glyph_order",(rs,n)->rs.getObject(1,UUID.class),sampleId),ordered=feedback.glyphOrder()==null||feedback.glyphOrder().isEmpty()?stored:feedback.glyphOrder();List<String> edited=feedback.glyphImagesBase64()==null?List.of():feedback.glyphImagesBase64();
  if(!edited.isEmpty()){if(edited.size()!=corrected.length())throw new IllegalArgumentException("Edited glyph image count must match corrected text length.");db.update("DELETE FROM invoice_desk_gdt_captcha_glyph WHERE sample_id=?",sampleId);for(int i=0;i<edited.size();i++){byte[] png;try{png=Base64.getDecoder().decode(edited.get(i));}catch(Exception e){throw new IllegalArgumentException("Edited glyph image is not valid Base64.");}if(png.length==0||png.length>512*1024)throw new IllegalArgumentException("Each edited glyph PNG must be between 1 byte and 512 KiB.");var item=GdtCaptchaImage.template(png);db.update("INSERT INTO invoice_desk_gdt_captcha_glyph(id,sample_id,tenant_id,glyph_order,x,y,width,height,glyph_png,fingerprint,confirmed_char,confidence,accepted) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),sampleId,scope.tenantId(),i,0,0,item.image().getWidth(),item.image().getHeight(),GdtCaptchaImage.png(item.image()),item.fingerprint(),String.valueOf(corrected.charAt(i)),1d,feedback.correct());}
  }else if(corrected.length()!=stored.size()){byte[] source=db.queryForObject("SELECT source_png FROM invoice_desk_gdt_captcha_sample WHERE id=? AND tenant_id=?",byte[].class,sampleId,scope.tenantId());var analysis=GdtCaptchaImage.analyze(source,corrected.length());db.update("DELETE FROM invoice_desk_gdt_captcha_glyph WHERE sample_id=?",sampleId);for(int i=0;i<analysis.glyphs().size();i++){var item=analysis.glyphs().get(i);var box=item.box();db.update("INSERT INTO invoice_desk_gdt_captcha_glyph(id,sample_id,tenant_id,glyph_order,x,y,width,height,glyph_png,fingerprint,confirmed_char,accepted) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),sampleId,scope.tenantId(),i,box.x(),box.y(),box.width(),box.height(),GdtCaptchaImage.png(item.image()),item.fingerprint(),String.valueOf(corrected.charAt(i)),feedback.correct());}db.update("UPDATE invoice_desk_gdt_captcha_sample SET cleaned_png=?,review_png=? WHERE id=?",GdtCaptchaImage.png(analysis.cleaned()),GdtCaptchaImage.png(analysis.review()),sampleId);
  }else{if(new HashSet<>(ordered).size()!=stored.size()||!new HashSet<>(ordered).equals(new HashSet<>(stored)))throw new IllegalArgumentException("Glyph order is invalid.");db.update("UPDATE invoice_desk_gdt_captcha_glyph SET accepted=false,confirmed_char='',glyph_order=-glyph_order-1 WHERE sample_id=?",sampleId);for(int i=0;i<ordered.size();i++)db.update("UPDATE invoice_desk_gdt_captcha_glyph SET glyph_order=?,confirmed_char=?,accepted=? WHERE id=? AND sample_id=?",i,String.valueOf(corrected.charAt(i)),feedback.correct(),ordered.get(i),sampleId);}
  db.update("UPDATE invoice_desk_gdt_captcha_sample SET corrected_text=?,review_state=?,reviewed_at=? WHERE id=? AND tenant_id=?",corrected,feedback.correct()?"CORRECT":"INCORRECT",Timestamp.from(Instant.now()),sampleId,scope.tenantId());
 }
 public Map<String,Object> library(InvoiceDeskService.Scope scope){var learned=new HashMap<String,CharacterSummary>();var rows=db.query("SELECT g.confirmed_char,COUNT(*),MIN(s.created_at),MAX(s.created_at) FROM invoice_desk_gdt_captcha_glyph g JOIN invoice_desk_gdt_captcha_sample s ON s.id=g.sample_id WHERE g.tenant_id=? AND s.company_id=? AND g.accepted=true AND g.confirmed_char<>'' GROUP BY g.confirmed_char",(rs,n)->new CharacterSummary(rs.getString(1),rs.getLong(2),rs.getTimestamp(3).toInstant().toString(),rs.getTimestamp(4).toInstant().toString()),scope.tenantId(),scope.companyId());for(var row:rows)learned.put(row.character(),row);var characters=new ArrayList<CharacterSummary>();String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";for(int i=0;i<alphabet.length();i++){String character=String.valueOf(alphabet.charAt(i));characters.add(learned.getOrDefault(character,new CharacterSummary(character,0,"","")));}return Map.of("characters",List.copyOf(characters),"learned",learned.size(),"total",alphabet.length());}
 public Map<String,Object> character(InvoiceDeskService.Scope scope,String value){String character=clean(value);if(character.length()!=1)throw new IllegalArgumentException("One letter or number is required.");var variants=db.query("SELECT g.id,g.sample_id,g.glyph_png,g.confidence,s.created_at FROM invoice_desk_gdt_captcha_glyph g JOIN invoice_desk_gdt_captcha_sample s ON s.id=g.sample_id WHERE g.tenant_id=? AND s.company_id=? AND g.accepted=true AND g.confirmed_char=? ORDER BY s.created_at DESC",(rs,n)->new CharacterVariant(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),Base64.getEncoder().encodeToString(rs.getBytes(3)),rs.getDouble(4),rs.getTimestamp(5).toInstant().toString()),scope.tenantId(),scope.companyId(),character);return Map.of("character",character,"variants",variants);}
 @Transactional public Map<String,Object> replaceVariant(InvoiceDeskService.Scope scope,UUID id,byte[] image)throws Exception{if(image==null||image.length==0||image.length>2*1024*1024)throw new IllegalArgumentException("Character PNG must be between 1 byte and 2 MiB.");var glyph=GdtCaptchaImage.template(image);byte[] normalized=GdtCaptchaImage.png(glyph.image());int changed=db.update("UPDATE invoice_desk_gdt_captcha_glyph g SET glyph_png=?,fingerprint=?,confidence=1,accepted=true WHERE g.id=? AND g.tenant_id=? AND EXISTS(SELECT 1 FROM invoice_desk_gdt_captcha_sample s WHERE s.id=g.sample_id AND s.company_id=?)",normalized,glyph.fingerprint(),id,scope.tenantId(),scope.companyId());if(changed!=1)throw new IllegalArgumentException("Learned character shape was not found.");return Map.of("id",id,"imageBase64",Base64.getEncoder().encodeToString(normalized),"confidence",1d);}
 @Transactional public void removeVariant(InvoiceDeskService.Scope scope,UUID id){int changed=db.update("UPDATE invoice_desk_gdt_captcha_glyph g SET accepted=false WHERE g.id=? AND g.tenant_id=? AND EXISTS(SELECT 1 FROM invoice_desk_gdt_captcha_sample s WHERE s.id=g.sample_id AND s.company_id=?)",id,scope.tenantId(),scope.companyId());if(changed!=1)throw new IllegalArgumentException("Learned character shape was not found.");}
 private Match match(UUID tenant,String fingerprint){var rows=db.query("SELECT confirmed_char,fingerprint FROM invoice_desk_gdt_captcha_glyph WHERE tenant_id=? AND accepted=true",(rs,n)->new String[]{rs.getString(1),rs.getString(2)},tenant);String best="";double score=0;for(String[] row:rows){double current=GdtCaptchaImage.similarity(fingerprint,row[1]);if(current>score){score=current;best=row[0];}}return score>=.82?new Match(best,score):new Match("",score);}
 private Candidate candidate(UUID tenant,byte[] source,int expected)throws Exception{var analysis=GdtCaptchaImage.analyze(source,expected);List<Glyph> glyphs=new ArrayList<>();List<Pending> pending=new ArrayList<>();StringBuilder local=new StringBuilder();int order=0;for(var item:analysis.glyphs()){Match match=match(tenant,item.fingerprint());String predicted=match.value();local.append(predicted.isEmpty()?"?":predicted);UUID id=UUID.randomUUID();var box=item.box();pending.add(new Pending(id,order,item,match));glyphs.add(new Glyph(id,order++,box.x(),box.y(),box.width(),box.height(),Base64.getEncoder().encodeToString(GdtCaptchaImage.png(item.image())),predicted,match.confidence()));}return new Candidate(analysis,List.copyOf(pending),List.copyOf(glyphs),local.toString());}
 private static boolean strong(Candidate candidate){return candidate.glyphs().size()==6&&!candidate.text().contains("?")&&candidate.glyphs().stream().allMatch(g->g.confidence()>=.92);}
 private static String choose(String google,String local,List<Glyph> glyphs){boolean complete=!local.contains("?")&&!local.isEmpty(),strong=complete&&glyphs.stream().allMatch(g->g.confidence()>=.92);return strong?local:google.isEmpty()?(complete?local:""):google;}
 private static String clean(String value){String text=Objects.toString(value,"").replaceAll("[^A-Za-z0-9]","");if(text.length()>32)throw new IllegalArgumentException("CAPTCHA text is too long.");return text;}
}
